/** Generated by scaffold-crud-pages. Query hooks for Families.
 *
 * Every read is a `useQuery`, every write a `useMutation` that invalidates the
 * domain on success. Nothing here re-fetches by hand — the invalidation IS the
 * refresh, which is what keeps two screens from disagreeing about one record.
 */
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { qk } from '~/queries/keys';
import {
  fetchFamiliesList,
  fetchFamiliesById,
  createFamilies,
  updateFamilies,
  deleteFamilies,
  type FetchFamiliesListParams,
} from '~/services/httpServices/familiesService';
import type { CreateFamiliesRequest, UpdateFamiliesRequest } from '~/types/families';

const DOMAIN = 'families';

export function useFamiliesList(params?: FetchFamiliesListParams) {
  return useQuery({
    queryKey: qk.list(DOMAIN, params),
    queryFn: () => fetchFamiliesList(params),
  });
}

export function useFamilies(id: string | undefined) {
  return useQuery({
    queryKey: qk.detail(DOMAIN, id ?? ''),
    queryFn: () => fetchFamiliesById(id as string),
    enabled: Boolean(id),
  });
}

export function useCreateFamilies() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (body: CreateFamiliesRequest) => createFamilies(body),
    onSuccess: () => qc.invalidateQueries({ queryKey: qk.all(DOMAIN) }),
  });
}

export function useUpdateFamilies() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: ({ id, body }: { id: string; body: UpdateFamiliesRequest }) =>
      updateFamilies(id, body),
    onSuccess: (_data, { id }) => {
      qc.invalidateQueries({ queryKey: qk.detail(DOMAIN, id) });
      qc.invalidateQueries({ queryKey: qk.list(DOMAIN) });
    },
  });
}

export function useDeleteFamilies() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (id: string) => deleteFamilies(id),
    onSuccess: () => qc.invalidateQueries({ queryKey: qk.all(DOMAIN) }),
  });
}
